// Originally generated by `archegraph testgen`, then HAND-REPAIRED so it
// typechecks. Regenerating this file discards those repairs.

import { describe, expect, test } from 'bun:test';
import * as fc from 'fast-check';

import { commandPaletteItems } from '../src/shell/palette_items';
import type { Command, CommandApplicability } from '../src/gestures/commands';
import type { KeymapEntry } from '../src/ui_state/keymap';

describe('testgen_shell__commandPaletteItems', () => {
    test('eligible_command', () => {
        fc.assert(
            fc.property(fc.record({ label: fc.string(), appliesTo: fc.constantFrom('global', ['node']) as fc.Arbitrary<CommandApplicability> , hasBinding: fc.boolean() }), (value) => {
        const command: Command = {
          id: 'duplicate',
          label: value.label,
          appliesTo: value.appliesTo,
          run: () => undefined,
        };
        const keymap: KeymapEntry[] = value.hasBinding
          ? [{ command: 'duplicate', chord: { key: 'x', meta: false, shift: false } }]
          : [];
        const items = commandPaletteItems([command], keymap);
        expect(items).toEqual([
          {
            key: 'command:duplicate',
            label: value.label,
            detail: value.hasBinding ? 'X' : '',
            action: { kind: 'command', command: 'duplicate' },
          },
        ]);
            })
        );
    });

    test('inapplicable_command', () => {
        fc.assert(
            fc.property(fc.string(), (value) => {
        const command: Command = {
          id: 'duplicate',
          label: value,
          run: () => undefined,
        };
        expect(commandPaletteItems([command], [])).toEqual([]);
            })
        );
    });

    // WHEN: A command has id 'open-palette'; it is skipped even when appliesTo is present.
    // THEN: Skips the command even when appliesTo is present.
    test('palette_self_reference', () => {
        const command: Command = {
          id: 'open-palette',
          label: 'Open palette',
          appliesTo: 'global',
          run: () => undefined,
        };
        expect(commandPaletteItems([command], [])).toEqual([]);
    });

    // WHEN: A command has id 'open-help'; it is included when it has appliesTo present, rather than being excluded merely because it is a global command.
    // THEN: Includes open-help when appliesTo is present, despite it being a global command.
    test('help_command_listed', () => {
        const command: Command = {
          id: 'open-help',
          label: 'Keyboard Shortcuts',
          appliesTo: 'global',
          run: () => undefined,
        };
        expect(commandPaletteItems([command], [])).toEqual([
          {
            key: 'command:open-help',
            label: 'Keyboard Shortcuts',
            detail: '',
            action: { kind: 'command', command: 'open-help' },
          },
        ]);
    });

    test('matching_keymap_entry', () => {
        fc.assert(
            fc.property(fc.array(fc.record({ key: fc.constant('x'), meta: fc.constant(false), shift: fc.constant(false) }), { minLength: 1 }), (value) => {
        const command: Command = {
          id: 'duplicate',
          label: 'Copy',
          appliesTo: 'global',
          run: () => undefined,
        };
        const keymap: KeymapEntry[] = value.map((chord) => ({ command: 'duplicate', chord }));
        const items = commandPaletteItems([command], keymap);
        expect(items[0]?.detail).toBe('X');
            })
        );
    });

    // WHEN: An included command has no keymap entry whose command equals its id; its detail is the empty string.
    // THEN: Sets the included command's detail to the empty string.
    test('missing_keymap_entry', () => {
        const command: Command = {
          id: 'duplicate',
          label: 'Copy',
          appliesTo: 'global',
          run: () => undefined,
        };
        const items = commandPaletteItems([command], []);
        expect(items).toEqual([
          {
            key: 'command:duplicate',
            label: 'Copy',
            detail: '',
            action: { kind: 'command', command: 'duplicate' },
          },
        ]);
    });

    test('command_order_preserved', () => {
        fc.assert(
            fc.property(fc.array(fc.boolean()), (value) => {
        const commands: Command[] = value.map((included, index) => ({
          id: 'duplicate',
          label: String(index),
          ...(included ? { appliesTo: 'global' } : {}),
          run: () => undefined,
        }));
        const items = commandPaletteItems(commands, []);
        expect(items.map((item) => item.label)).toEqual(
          value
            .map((included, index) => (included ? String(index) : undefined))
            .filter((label) => label !== undefined),
        );
            })
        );
    });

    // WHEN: The commands input is empty; the function returns an empty array.
    // THEN: Returns an empty array.
    test('empty_command_list', () => {
        expect(commandPaletteItems([], [])).toEqual([]);
    });

});

